const TOOL_INPUT = $('Execute Workflow Trigger').first().json;
const CLINIC_ID = TOOL_INPUT.clinic_id;
const CLINIC_TIMEZONE = TOOL_INPUT.timezone;
if (!CLINIC_ID || !CLINIC_TIMEZONE) throw new Error('clinic_id and timezone are required tool inputs');
const CANCELLATION_CUTOFF_MINUTES = Number.isFinite(Number(TOOL_INPUT.cancellation_cutoff_minutes ?? ''))
  && String(TOOL_INPUT.cancellation_cutoff_minutes ?? '') !== ''
  ? Number(TOOL_INPUT.cancellation_cutoff_minutes)
  : 15;
const phone = $('Execute Workflow Trigger').first().json.phone_number;
const base = $env.SUPABASE_URL;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const headers = {
  apikey: key,
  Authorization: 'Bearer ' + key,
  'Content-Type': 'application/json',
  Prefer: 'return=representation',
};

function formatTime12h(raw) {
  const s = String(raw || '').trim();
  const dt = DateTime.fromFormat(s, 'HH:mm', { zone: CLINIC_TIMEZONE, locale: 'en' });
  if (!dt.isValid) return s;
  return dt.setLocale('en-US').toFormat('h:mm a').replace(/\b(am|pm)\b/gi, (m) => m.toUpperCase());
}

function formatDateDisplay(isoOrDate) {
  const raw = String(isoOrDate || '').trim();
  const datePart = raw.includes('T') ? raw.split('T')[0] : raw.slice(0, 10);
  const dt = DateTime.fromISO(datePart, { zone: CLINIC_TIMEZONE });
  return dt.isValid ? dt.toFormat('MMMM d, yyyy') : raw;
}

const rows = await this.helpers.httpRequest({
  method: 'GET',
  url: `${base}/rest/v1/appointments?clinic_id=eq.${encodeURIComponent(CLINIC_ID)}&phone_number=eq.${encodeURIComponent(phone)}&status=in.(booked,confirmed)&select=*&order=appointment_date.asc`,
  headers,
  json: true,
});

const appointments = Array.isArray(rows) ? rows : [];
if (!appointments.length) {
  return [{ json: { success: true, cancelled_count: 0, message: 'No active appointments were found for this phone number.' } }];
}

const now = DateTime.now().setZone(CLINIC_TIMEZONE);
const cancelled = [];
const skipped = [];
const failed = [];

for (const appt of appointments) {
  const datePart = String(appt.appointment_date || '').includes('T')
    ? DateTime.fromISO(appt.appointment_date, { zone: CLINIC_TIMEZONE }).toFormat('yyyy-MM-dd')
    : String(appt.appointment_date || '').slice(0, 10);
  const timePart = String(appt.appointment_time || '').slice(0, 5);
  const apptDateTime = DateTime.fromFormat(`${datePart} ${timePart}`, 'yyyy-MM-dd HH:mm', { zone: CLINIC_TIMEZONE });
  const label = `${formatDateDisplay(appt.appointment_date)} at ${formatTime12h(appt.appointment_time)} (${appt.appointment_id})`;

  if (apptDateTime.isValid) {
    const minutesUntil = apptDateTime.diff(now, 'minutes').minutes;
    if (minutesUntil <= 0) {
      skipped.push(`${label}: already passed`);
      continue;
    }
    if (minutesUntil <= CANCELLATION_CUTOFF_MINUTES) {
      skipped.push(`${label}: too close to appointment time`);
      continue;
    }
  }

  try {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${base}/rest/v1/appointments?clinic_id=eq.${encodeURIComponent(CLINIC_ID)}&appointment_id=eq.${encodeURIComponent(appt.appointment_id)}`,
      headers,
      body: { status: 'cancelled' },
      json: true,
    });
    cancelled.push(label);
  } catch (e) {
    failed.push(`${label}: could not cancel`);
  }
}

const parts = [];
if (cancelled.length) {
  parts.push(`Cancelled ${cancelled.length} appointment(s):\n- ${cancelled.join('\n- ')}`);
}
if (skipped.length) {
  parts.push(`Skipped ${skipped.length} appointment(s):\n- ${skipped.join('\n- ')}`);
}
if (failed.length) {
  parts.push(`Could not cancel ${failed.length} appointment(s):\n- ${failed.join('\n- ')}`);
}
if (!parts.length) {
  parts.push('No appointments could be cancelled.');
}

return [{
  json: {
    success: cancelled.length > 0,
    cancelled_count: cancelled.length,
    skipped_count: skipped.length,
    failed_count: failed.length,
    message: parts.join('\n\n'),
  },
}];
